        let bc = cands[0], bs = -1e9;
        for (const c of cands) { const sc = userScore(c, counts[t], dem, strategy, sf, pickNum); if (sc > bs) { bs = sc; bc = c; } }
        drafted[bc.id] = 1; counts[t][bc.pos]++; recent = [...recent.slice(-7), bc.pos];
        continue;
