  const kv = [
    { k: "Pos rank", v: `${p.pos}${p.posRank}`, c: rankTierColor(p.pos, p.posRank) },
    { k: "Fantasy", v: p.fantasyTier || "—" },
    { k: "Proj pts", v: `${p.pts}` },
    { k: "ADP", v: p.adp != null ? p.adp.toFixed(1) : "—" },
  ];
